contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address caller) public payable {
        require(caller != address(0), "caller must be nonzero");
        bool reverted;
        if (caller == address(this)) {
            c.sudicideAnyone();
            reverted = false;
        } else {
            (bool ok, ) = address(c).call(abi.encodeWithSignature("sudicideAnyone()"));
            reverted = !ok;
        }
        assert(reverted == (caller != address(this)));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    address public smartfix_owner_before;
    constructor(C _c) {
        c = _c;
        smartfix_owner_before = c.smartfix_owner();
    }

    function run() public payable {
        require(smartfix_owner_before != address(this), "owner is the test contract");
        bool reverted;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) {
        c = _c;
    }

    function run(uint256 nonce) public payable {
        require(nonce == nonce, "nonce unused");
        address ownerBefore = c.smartfix_owner();
        require(ownerBefore != address(this), "test contract is owner");
        uint256 codeSizeBefore = address(c).code.length;
        bool reverted;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 codeSizeAfter = address(c).code.length;
        assert(reverted && codeSizeAfter == codeSizeBefore && codeSizeBefore > 0);
    }

    receive() external payable {}
}
